import json, random, copy, collections, sys, subprocess, pathlib
sys.path.insert(0,'/workspace/submission')
from main import transport

def topo(t):
    typ=t[0]
    if typ=='clos':
        k,scope,intra=t[1:];n=k*k;r=k//2;T=n//2
        return n,[(s, d, (s//r if scope=='pod' else s), {s,d}|{T+p*r+i for p in {s//r,d//r} for i in range(r)}) for s in range(T) for d in range(T) if s!=d and (intra or s//r!=d//r)]
    if typ=='leaf-spine':
        l,s=t[1:];return l+s,[(x,y,x,{x,y}) for x in range(l) for y in range(l) if x!=y]
    if typ in ('torus2d','torus3d'):
        side,scope=t[1:];dim=2 if typ=='torus2d' else 3;n=side**dim;ep=list(range(n));dom=lambda s,d:s if scope=='host' else s//side
    elif typ=='dragonfly':
        g,a,h,scope=t[1:];n=g*a;ep=list(range(n))
        dom=lambda s,d: s if scope=='router' else s//a if scope=='group' else s*g+d//a
    else:
        g,l,s,h,dense,scope=t[1:];n=g*(l+s);ep=[j*(l+s)+i for j in range(g) for i in range(l)]
        dom=lambda x,y:x//(l+s) if scope=='group' else x//(l+s)*l+x%(l+s)
    adj=[set() for _ in range(n)]
    def edge(x,y):adj[x].add(y);adj[y].add(x)
    if typ in ('torus2d','torus3d'):
        for x in range(n):
            for ax in range(dim):
                step=side**ax
                edge(x,x+step if x//step%side<side-1 else x-(side-1)*step)
    elif typ=='dragonfly':
        for j in range(g):
            for x in range(a):
                for y in range(x):edge(j*a+x,j*a+y)
        for i in range(g):
            for j in range(i+1,g):
                delta=j-i;edge(i*a+(delta-1)//h,j*a+(g-delta-1)//h)
    else:
        for j in range(g):
            for x in range(l):
                for y in range(s):edge(j*(l+s)+x,j*(l+s)+l+y)
        for i in range(g):
            for j in range(i+1,g):
                if dense:
                    for x in range(s):edge(i*(l+s)+l+x,j*(l+s)+l+x)
                else:
                    delta=j-i;edge(i*(l+s)+l+(delta-1)//h,j*(l+s)+l+(g-delta-1)//h)
    dist=[]
    for src in range(n):
        row=[100000]*n;row[src]=0;q=collections.deque([src])
        while q:
            x=q.popleft()
            for y in adj[x]:
                if row[y]>row[x]+1:row[y]=row[x]+1;q.append(y)
        dist.append(row)
    return n,[(x,y,dom(x,y),{z for z in range(n) if dist[x][z]+dist[z][y]==dist[x][y]}) for x in ep for y in ep if x!=y]

def summary(s,templates):
    g=len(s['groups']);n=len(s['caps']);counts=[0]*g;loads=[0]*g;pairs=[set() for _ in range(g)];fp=[set() for _ in range(g)];usage=[0]*n
    for t,gid,w,c,p in s['tasks']:
        counts[gid]+=1;loads[gid]+=w;pairs[gid].add((templates[t][2],c));fp[gid]|=templates[t][3]
    for gid,(q,b) in enumerate(s['groups']):
        for x in fp[gid]:usage[x]+=q
    v=[sum(x>c for x,c in zip(usage,s['caps'])),sum(len(p)>1 for p in pairs),sum(counts[x]>0 and (s['groups'][x][0]==0 or loads[x]>s['groups'][x][0]*s['groups'][x][1]) for x in range(g))]
    return counts,loads,pairs,fp,usage,v

def cert(s,templates,q):
    counts,loads,pairs,fp,usage,_=summary(s,templates)
    return {'totals':[sum(x>0 for x in counts),sum(usage),sum(t[2] for t in s['tasks']),sum(t[4] for t in s['tasks'])],
      'groups':[[i,counts[i],loads[i],*s['groups'][i],len(fp[i]),*(next(iter(pairs[i])) if counts[i] else (-1,-1))] for i in q['groups']],
      'nodes':[[i,usage[i],s['caps'][i]] for i in q['nodes']],
      'tasks':[[i,s['tasks'][i][1],s['tasks'][i][0],*s['tasks'][i][2:]] for i in q['tasks']]}

def apply(s,templates,tx,rev):
    if tx['revision']!=rev:
        return s,{'accepted':False,'revision':rev,'violations':None,'certificate':cert(s,templates,tx['query'])}
    p=copy.deepcopy(s)
    for op,i,val in tx['edits']:
        if op=='cap':p['caps'][i]=val
        elif op=='quota':p['groups'][i][0]=val
        elif op=='budget':p['groups'][i][1]=val
        else:p['tasks'][i][{'bind':0,'move':1,'weight':2,'class':3,'pin':4}[op]]=val
    v=summary(p,templates)[-1]
    v.append(sum(old[4] and (old[:4]!=new[:4] or s['groups'][old[1]][0]!=p['groups'][old[1]][0]) for old,new in zip(s['tasks'],p['tasks'])))
    accept=not any(v)
    if accept:s=p;rev+=1
    return s,{'accepted':accept,'revision':rev,'violations':v,'certificate':cert(s,templates,tx['query'])}

def generate(r,t,ntx=100):
    n,templates=topo(t);g=r.randint(1,25);d=r.randint(1,80)
    bydom=collections.defaultdict(list)
    for i,x in enumerate(templates):bydom[x[2]].append(i)
    gc=[(r.choice(list(bydom)),r.choice([0,1,2,10**9])) for _ in range(g)]
    s={'topology':t,'caps':[10**9]*n,'groups':[[r.randint(0,5),1] for _ in range(g)],'tasks':[]}
    for i in range(d):
        gid=r.randrange(g);dom,c=gc[gid]
        s['tasks'].append([r.choice(bydom[dom]),gid,r.choice([1,2,50,10**9]),c,r.randrange(4)==0])
        s['tasks'][-1][-1]=int(s['tasks'][-1][-1])
    counts,loads,_,_,usage,_=summary(s,templates)
    for i in range(g):
        if counts[i] and not s['groups'][i][0]:s['groups'][i][0]=r.randint(1,5)
        q=s['groups'][i][0]
        s['groups'][i][1]=r.choice([10**12,(loads[i]+max(q,1)-1)//max(q,1)+1])
    usage=summary(s,templates)[4]
    s['caps']=[u+r.randint(0,2) for u in usage]
    def query():return {'groups':[r.randrange(g) for _ in range(r.randint(0,5))],'nodes':[r.randrange(n) for _ in range(r.randint(0,5))],'tasks':[r.randrange(d) for _ in range(r.randint(0,5))]}
    s['query']=query();out={'nodes':n,'templates':len(templates),'initial':cert(s,templates,s['query']),'transactions':[]}
    ss=copy.deepcopy(s);rev=0;s['transactions']=[]
    for j in range(ntx):
        edits=[]
        typ=r.randrange(8)
        if typ==0:
            # Change then restore assignments, testing final-value semantics.
            op=r.choice(['move','bind','weight','class','pin','quota','budget','cap']);i=r.randrange(d if op in ['move','bind','weight','class','pin'] else n if op=='cap' else g)
            val=r.choice([0,1,2]) if op in ['class','quota','cap'] else r.randint(1,3) if op in ['weight','budget'] else r.randrange(g) if op=='move' else r.randrange(len(templates)) if op=='bind' else r.randrange(2)
            old=ss['caps'][i] if op=='cap' else ss['groups'][i][op=='budget'] if op in ['budget','quota'] else ss['tasks'][i][{'move':1,'bind':0,'weight':2,'class':3,'pin':4}[op]]
            edits=[[op,i,val],[op,i,old]]
        elif typ==1:
            # Unpin and modify another protected field, should still protect.
            i=r.randrange(d);edits=[['pin',i,0],['weight',i,r.choice([1,50,10**9])]]
        elif typ==2:
            # Quota changed and some tasks also changed: pin count not doubled.
            gid=r.randrange(g);ids=[i for i,task in enumerate(ss['tasks']) if task[1]==gid]
            edits=[['quota',gid,r.randrange(7)],['budget',gid,10**12]]+[['pin',i,0] for i in ids]+[['class',i,r.choice([0,1])] for i in ids]
        elif typ==3:
            # Try changing the whole group to another pair, with adequate work.
            gid=r.randrange(g);tt=r.randrange(len(templates));cc=r.choice([0,2,10**9])
            edits=[['bind',i,tt] for i,task in enumerate(ss['tasks']) if task[1]==gid]+[['class',i,cc] for i,task in enumerate(ss['tasks']) if task[1]==gid]
        elif typ>3:
            for _ in range(r.randint(0,15)):
                op=r.choice(['move','bind','weight','class','pin','quota','budget','cap'])
                i=r.randrange(d if op in ['move','bind','weight','class','pin'] else n if op=='cap' else g)
                val=r.choice([0,1,2,10**9]) if op in ['class','cap'] else r.choice([0,1,2,64]) if op=='quota' else r.choice([1,2,50,10**9]) if op=='weight' else r.choice([1,2,50,10**12]) if op=='budget' else r.randrange(g) if op=='move' else r.randrange(len(templates)) if op=='bind' else r.randrange(2)
                edits.append([op,i,val])
        tx={'revision':rev if r.random()<.85 else r.randrange(rev+10),'edits':edits,'query':query()}
        s['transactions'].append(tx);ss,o=apply(ss,templates,tx,rev);rev=o['revision'];out['transactions'].append(o)
    return s,out

def runcheck(request,expected,entry=False):
    if entry:
        cmd=['python3','-B','/workspace/submission/main.py'];data=json.dumps(request).encode()
    else:
        cmd=['/workspace/tmp/unit-merge-build/engine'];data=transport(request)
    p=subprocess.run(cmd,input=data,capture_output=True)
    assert p.returncode==0,(p.returncode,p.stderr)
    actual=json.loads(p.stdout)
    if actual!=expected:
        pathlib.Path('/workspace/bad-request.json').write_text(json.dumps(request))
        pathlib.Path('/workspace/bad-actual.json').write_text(json.dumps(actual))
        pathlib.Path('/workspace/bad-expected.json').write_text(json.dumps(expected))
        if 'sessions' in actual and 'sessions' in expected:
            for i,(a,e) in enumerate(zip(actual['sessions'],expected['sessions'])):
                if a!=e:
                    print('Session',i,request['sessions'][i]['topology'])
                    if a['initial']!=e['initial']:print('Initial',a['initial'],e['initial'])
                    for j,(aa,ee) in enumerate(zip(a['transactions'],e['transactions'])):
                        if aa!=ee:print('Transaction',j,request['sessions'][i]['transactions'][j],aa,ee);break
                    break
        raise AssertionError('mismatch')

if __name__=='__main__':
    for f in json.loads(pathlib.Path('/workspace/examples/checks.json').read_text()):
        data=f.get('raw') or json.dumps(f['request'])
        p=subprocess.run(['python3','-B','/workspace/submission/main.py'],input=data.encode(),capture_output=True)
        assert p.returncode==0,(p.returncode,p.stderr)
        assert json.loads(p.stdout)==f['response'],(f,p.stdout)
    print('All nine public fixtures match (direct subprocess; public supervisor unavailable).')
    ts=[['clos',4,'pod',0],['clos',6,'tor',1],['leaf-spine',8,3],['torus2d',4,'row'],['torus2d',5,'host'],['torus3d',4,'line'],['torus3d',3,'host'],['dragonfly',5,2,2,'target'],['dragonfly',7,3,2,'group'],['dragonfly',4,3,1,'router'],['dragonfly-plus',3,2,2,1,0,'tor'],['dragonfly-plus',4,3,1,3,0,'group'],['dragonfly-plus',4,2,3,1,1,'group'],['dragonfly-plus',2,1,4,1,1,'tor']]
    for seed in range(40):
        r=random.Random(seed);req={'version':2,'sessions':[]};exp={'sessions':[]}
        for t in ts:
            s,o=generate(r,t,100);req['sessions'].append(s);exp['sessions'].append(o)
        runcheck(req,exp,entry=(seed%20==0))
        print('random batch',seed,'matches')
